import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { useShopCart } from "../ShopCartContext";
import { FiShoppingCart } from "react-icons/fi";

const FloatingCartBar = () => {
  const { shopCartItems } = useShopCart();
  const navigate = useNavigate();
  const [isModalOpen, setIsModalOpen] = useState(false);

  useEffect(() => {
    const checkModalState = () => {
      const isLocked = document.body.style.overflow === "hidden" || document.body.classList.contains("modal-open");
      const hasOverlay = !!document.querySelector(".uam-overlay, .registration-modal-overlay, [data-modal-open='true']");
      setIsModalOpen(isLocked || hasOverlay);
    };

    checkModalState();

    const observer = new MutationObserver(() => {
      checkModalState();
    });

    observer.observe(document.body, {
      attributes: true,
      attributeFilter: ["style", "class"],
      childList: true,
      subtree: true,
    });

    return () => observer.disconnect();
  }, []);

  if (!shopCartItems || shopCartItems.length === 0 || isModalOpen) {
    return null;
  }

  const totalItems = shopCartItems.reduce(
    (sum, item) => sum + (Number(item?.quantity) || 1),
    0
  );

  const totalPrice = shopCartItems.reduce((sum, item) => {
    const price = Number(item?.price || item?.mrp || item?.salePrice || 0);
    const qty = Number(item?.quantity) || 1;
    return sum + price * qty;
  }, 0);

  return (
    <>
      <style>{`
        .floating-cart-bar-container {
          position: fixed;
          bottom: 24px;
          left: 50%;
          transform: translateX(-50%);
          width: calc(100% - 32px);
          max-width: 680px;
          background-color: #ffffff;
          border-radius: 16px;
          box-shadow: 0 12px 32px -4px rgba(168, 71, 240, 0.2), 0 4px 16px rgba(0, 0, 0, 0.1);
          border: 1.5px solid #E9D5FF;
          padding: 12px 20px;
          display: flex;
          justify-content: space-between;
          align-items: center;
          z-index: 1000;
          animation: slideUpFloatingCart 0.3s cubic-bezier(0.16, 1, 0.3, 1) forwards;
        }

        @media (max-width: 1023px) {
          .floating-cart-bar-container {
            bottom: 74px !important;
            width: calc(100% - 20px) !important;
            padding: 10px 14px !important;
            border-radius: 14px !important;
          }
          .floating-cart-icon-wrapper {
            width: 38px !important;
            height: 38px !important;
          }
          .floating-cart-icon-wrapper svg {
            width: 18px !important;
            height: 18px !important;
          }
          .floating-cart-price {
            font-size: 15px !important;
          }
          .floating-cart-items-text {
            font-size: 11.5px !important;
          }
          .floating-cart-view-btn {
            padding: 8px 18px !important;
            font-size: 13.5px !important;
          }
        }

        @keyframes slideUpFloatingCart {
          from {
            opacity: 0;
            transform: translate(-50%, 25px);
          }
          to {
            opacity: 1;
            transform: translate(-50%, 0);
          }
        }

        .floating-cart-view-btn {
          background: linear-gradient(135deg, #A847F0 0%, #8B5CF6 100%);
          color: #ffffff;
          transition: all 0.2s ease;
          border: none;
          font-weight: 700;
          font-size: 15px;
          padding: 10px 26px;
          border-radius: 10px;
          cursor: pointer;
          display: inline-flex;
          align-items: center;
          justify-content: center;
          white-space: nowrap;
        }
        .floating-cart-view-btn:hover {
          background: linear-gradient(135deg, #9333EA 0%, #7C3AED 100%);
          transform: translateY(-1px);
          box-shadow: 0 4px 14px rgba(168, 71, 240, 0.45);
        }
        .floating-cart-view-btn:active {
          transform: translateY(0);
        }
      `}</style>

      <div className="floating-cart-bar-container">
        {/* Left Details: Icon + Price & Count */}
        <div
          className="d-flex align-items-center"
          style={{ gap: "12px", cursor: "pointer" }}
          onClick={() => navigate("/medicine/cart")}
        >
          <div
            className="floating-cart-icon-wrapper"
            style={{
              width: "44px",
              height: "44px",
              borderRadius: "50%",
              backgroundColor: "#F3E8FF",
              color: "#A847F0",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              flexShrink: 0,
              boxShadow: "inset 0 0 0 1px rgba(168, 71, 240, 0.18)",
            }}
          >
            <FiShoppingCart size={22} style={{ strokeWidth: "2.2" }} />
          </div>

          <div className="d-flex flex-column justify-content-center">
            <span
              className="floating-cart-price"
              style={{
                fontSize: "17px",
                fontWeight: "800",
                color: "#0F172A",
                lineHeight: "1.2",
              }}
            >
              ₹{totalPrice.toLocaleString("en-IN")}
            </span>
            <span
              className="floating-cart-items-text"
              style={{
                fontSize: "13px",
                fontWeight: "500",
                color: "#64748B",
                lineHeight: "1.2",
                marginTop: "2px",
              }}
            >
              {totalItems} {totalItems === 1 ? "item" : "items"} added
            </span>
          </div>
        </div>

        {/* Right Action: View Cart Button */}
        <button
          type="button"
          className="floating-cart-view-btn"
          onClick={() => navigate("/medicine/cart")}
        >
          View Cart
        </button>
      </div>
    </>
  );
};

export default FloatingCartBar;
